contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint minSum, uint deposit, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (deposit)); require(deposit <= 1000000000000000000000000000000);
        require(minSum > 0);
        require(deposit > minSum);
        require(amount > deposit);
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.Deposit{value: deposit}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint minSumBefore = c.MinSum(); if (__ESBMC_reverted()) return;
        uint cEthBefore = address(c).balance;
        uint selfEthBefore = address(this).balance;
        c.Collect(amount); if (__ESBMC_reverted()) return;
        assert(
            c.balances(address(this)) == balBefore &&
            c.MinSum() == minSumBefore &&
            address(c).balance == cEthBefore &&
            address(this).balance == selfEthBefore
        );
    }
    receive() external payable {}
    fallback() external payable {}
}

