import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 minSum, uint256 deposit, uint256 amount) internal {
        deposit = bound(deposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(minSum > 0);
        vm.assume(deposit > minSum);
        vm.assume(amount > deposit);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: deposit}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 minSumBefore;
        try c.MinSum() returns (uint256 __r) { minSumBefore = __r; } catch { return; }
        uint cEthBefore = address(c).balance;
        uint selfEthBefore = address(this).balance;
        try c.Collect(amount) {} catch { return; }
        assertTrue(c.balances(address(this)) == balBefore &&
            c.MinSum() == minSumBefore &&
            address(c).balance == cEthBefore &&
            address(this).balance == selfEthBefore);
    }

    function testFuzz_run(uint256 minSum, uint256 deposit, uint256 amount) public {
        _run(minSum, deposit, amount);
    }

    receive() external payable {}

    fallback() external payable {}
}
